pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 w1, uint256 w2) internal {
        vm.assume(w1 <= address(c).balance);
        uint bal0 = address(c).balance;
        uint256 count0;
        try c.depositsCount() returns (uint256 __r) { count0 = __r; } catch { return; }
        try c.withdraw(w1) {} catch { return; }
        bool r2;
        try c.withdraw(w2) { r2 = false; } catch { r2 = true; }
        assertTrue(r2 == (w2 > bal0 - w1));
        if (r2) {
            assert(address(c).balance == bal0 - w1 && c.depositsCount() == count0);
        }
    }

    function testFuzz_run(uint256 w1, uint256 w2) public {
        _run(w1, w2);
    }

    receive() external payable {}
}
